#include <vector>
#include <iostream>

int main() {
    // Create a vector of 10 integers, each initialized to 0
    std::vector<int> v2(10);

    // Iterate and print the elements to demonstrate
    for(size_t i = 0; i < v2.size(); ++i) {
        std::cout << v2[i] << std::endl;  // Each will print 0
    }

    return 0;
}
